<?php
namespace AmitShaw\FCB;
defined('ABSPATH') || exit;

/** Local help stays usable until the proposed public documentation is published. */
final class Help {
    const PROPOSED_BASE_URL='https://github.com/Amitoshi/floating-chat-buttons#';
    public static function boot() { add_action('admin_enqueue_scripts',[self::class,'assets']); }
    public static function timezone_label() {
        $now=new \DateTimeImmutable('now',wp_timezone());
        return sprintf(__('Use website timezone (%1$s, UTC%2$s)','floating-chat-buttons-whatsapp-telegram-call'),wp_timezone_string(),$now->format('P'));
    }
    public static function documentation_base_url() {
        $base=defined('FCB_DOCS_BASE_URL') ? FCB_DOCS_BASE_URL : self::PROPOSED_BASE_URL;
        return trailingslashit(esc_url_raw(apply_filters('fcb_documentation_base_url',$base),['https']));
    }
    public static function documentation_url($topic) {
        $topics=self::topics();$topic=isset($topics[$topic])?$topic:'getting-started';
        $published=(bool)apply_filters('fcb_documentation_published',defined('FCB_DOCS_PUBLISHED') && FCB_DOCS_PUBLISHED);
        $base=self::documentation_base_url();
        return $published && $base!=='/' ? $base.'#'.$topic : admin_url('admin.php?page=fcb-help').'#'.$topic;
    }
    public static function assets($hook) {
        $page=isset($_GET['page']) && is_string($_GET['page']) ? sanitize_key(wp_unslash($_GET['page'])) : '';
        $pages=['fcb','fcb-buttons','fcb-design','fcb-inbox','fcb-hours','fcb-recovery','fcb-insights','fcb-integrations','fcb-display','fcb-advanced','fcb-setup','fcb-help'];
        if (!current_user_can('manage_options') || !in_array($page,$pages,true) || strpos($hook,'fcb')===false) { return; }
        wp_enqueue_style('fcb-admin-help',FCB_URL.'assets/admin-help.css',[],FCB_VERSION);
        wp_enqueue_script('fcb-admin-help',FCB_URL.'assets/admin-help.js',[],FCB_VERSION,true);
        $entries=self::registry();
        foreach($entries as &$entry){$entry['url']=self::documentation_url($entry['topic']);$entry['title']=self::topics()[$entry['topic']]['title'];}unset($entry);
        wp_localize_script('fcb-admin-help','FCBHelp',['entries'=>$entries,'timezoneLabel'=>self::timezone_label(),'read'=>'Read documentation','close'=>'Close help','help'=>'Help: ']);
    }
    public static function render() {
        $topics=self::topics();
        echo '<section class="fcb-local-guide" id="fcb-documentation-top" aria-label="Local documentation"><h2>Floating Chat Buttons documentation</h2><p>Complete help is available here inside WordPress. The proposed Amit Jyoti Shaw documentation website is not published yet. All topic links below work locally.</p><nav class="fcb-help-index" aria-label="Documentation topics"><ul>';
        foreach($topics as $id=>$topic){echo '<li><a href="#'.esc_attr($id).'">'.esc_html($topic['title']).'</a></li>';}
        echo '</ul></nav>';
        $labels=['what'=>'What it does','when'=>'When to use it','configure'=>'How to configure it','default'=>'Default behavior','example'=>'Example','limits'=>'Limits','troubleshoot'=>'Troubleshooting'];
        foreach($topics as $id=>$topic){
            echo '<article class="fcb-help-topic" id="'.esc_attr($id).'" tabindex="-1"><p class="fcb-help-category">'.esc_html($topic['category']).'</p><h3>'.esc_html($topic['title']).'</h3><dl>';
            foreach($labels as $key=>$label){echo '<dt>'.esc_html($label).'</dt><dd>'.nl2br(esc_html($topic[$key])).'</dd>';}
            echo '</dl><a href="#fcb-documentation-top">Back to documentation topics</a></article>';
        }
        echo '</section>';
    }
